class Pila[T]:
    def __init__(self) -> None:
        self._datos: list[T] = []

    def apilar(self, elemento: T) -> None:
        self._datos.append(elemento)

    def desapilar(self) -> T:
        if not self._datos:
            raise IndexError("desapilar de una pila vacía")
        return self._datos.pop()

    def cima(self) -> T | None:
        return self._datos[-1] if self._datos else None

    def __len__(self) -> int:
        return len(self._datos)


def vaciar[T](pila: Pila[T]) -> list[T]:
    resultado: list[T] = []
    while pila:
        resultado.append(pila.desapilar())
    return resultado

