from collections.abc import Iterable, Sequence
from typing import Protocol, runtime_checkable


@runtime_checkable
class ConArea(Protocol):
    def area(self) -> float: ...


def mayor[F: ConArea](figuras: Sequence[F]) -> F:
    if not figuras:
        raise ValueError("no hay figuras")
    for figura in figuras:
        if not isinstance(figura, ConArea):
            raise TypeError(f"{figura!r} no tiene un método area()")
    mejor = figuras[0]
    for figura in figuras[1:]:
        if figura.area() > mejor.area():
            mejor = figura
    return mejor


def area_total(figuras: Iterable[ConArea]) -> float:
    return float(sum(figura.area() for figura in figuras))

