def sumar(cadena: str) -> int:
    if cadena == "":
        return 0
    separadores = ["\n"]
    if cadena.startswith("//"):
        cabecera, _, cadena = cadena.partition("\n")
        delimitador = cabecera[2:]
        if not delimitador:
            raise ValueError("la cabecera no define ningún delimitador")
        separadores.append(delimitador)
    for separador in separadores:
        cadena = cadena.replace(separador, ",")
    numeros = [int(trozo) for trozo in cadena.split(",")]   # int('') o int('a') -> ValueError
    negativos = [n for n in numeros if n < 0]
    if negativos:
