import functools
import inspect
from typing import Any, Literal, Union, get_args, get_origin, get_type_hints


def cumple(valor: object, tipo: object) -> bool:
    """Indica si valor encaja con la anotación tipo (comprobación superficial)."""
    if tipo is Any:
        return True
    if tipo is None or tipo is type(None):
        return valor is None
    origen = get_origin(tipo)
    if origen is Union:
        return any(cumple(valor, opcion) for opcion in get_args(tipo))
    if origen is Literal:
        return valor in get_args(tipo)
    if origen is not None:                 # list[int], dict[str, int], Sequence[str]...
        return isinstance(valor, origen)
    if isinstance(tipo, type):
        return isinstance(valor, tipo)
    return True                            # anotaciones que no sabemos comprobar


def validar_tipos(func):
    firma = None                           # firma y anotaciones se calculan
    anotaciones = None                     # en la primera llamada

    def comprobar(nombre, valor):
        tipo = anotaciones.get(nombre, Any)
        if not cumple(valor, tipo):
            esperado = getattr(tipo, "__name__", str(tipo))
            raise TypeError(f"{nombre}: se esperaba {esperado}, se recibió {type(valor).__name__}")

    @functools.wraps(func)
    def envoltura(*args, **kwargs):
        nonlocal firma, anotaciones
        if anotaciones is None:
            firma = inspect.signature(func)      # ¡también evalúa las anotaciones!
            anotaciones = get_type_hints(func)
        ligados = firma.bind(*args, **kwargs)
        for nombre, valor in ligados.arguments.items():
            clase = firma.parameters[nombre].kind
            if clase is inspect.Parameter.VAR_POSITIONAL:
                for v in valor:
                    comprobar(nombre, v)
            elif clase is inspect.Parameter.VAR_KEYWORD:
                for v in valor.values():
                    comprobar(nombre, v)
            else:
                comprobar(nombre, valor)
        resultado = func(*args, **kwargs)
        comprobar("return", resultado)
        return resultado

    return envoltura

