from collections.abc import Callable, Iterable, Iterator
from typing import Any, Self, overload


class Coleccion[T]:
    def __init__(self, elementos: Iterable[T] = ()) -> None:
        self._elementos: tuple[T, ...] = tuple(elementos)

    def _nueva(self, elementos: Iterable[T]) -> Self:
        return type(self)(elementos)

    def filtrar(self, predicado: Callable[[T], bool]) -> Self:
        return self._nueva(x for x in self._elementos if predicado(x))

    def ordenar(self, *, clave: Callable[[T], Any] | None = None, inversa: bool = False) -> Self:
        return self._nueva(sorted(self._elementos, key=clave, reverse=inversa))

    @overload
    def __getitem__(self, indice: int) -> T: ...
    @overload
    def __getitem__(self, indice: slice) -> Self: ...
    def __getitem__(self, indice: int | slice) -> T | Self:
        if isinstance(indice, slice):
            return self._nueva(self._elementos[indice])
        return self._elementos[indice]

    def __len__(self) -> int:
        return len(self._elementos)

    def __iter__(self) -> Iterator[T]:
        return iter(self._elementos)

    def a_lista(self) -> list[T]:
        return list(self._elementos)

