from typing import (
    Annotated,
    Any,
    Literal,
    NotRequired,
    ReadOnly,
    Required,
    TypeAliasType,
    Union,
    get_args,
    get_origin,
    get_type_hints,
    is_typeddict,
)

_ENVOLTORIOS = (Required, NotRequired, ReadOnly)


def _error_tipo(ruta: str, esperado: str, valor: object) -> list[str]:
    return [f"{ruta}: se esperaba {esperado}, se recibió {type(valor).__name__}"]


def _validar_clase(datos: object, clase: type, ruta: str) -> list[str]:
    if isinstance(datos, bool) and clase in (int, float):
        return _error_tipo(ruta, clase.__name__, datos)      # en JSON, true no es un número
    if clase is float and isinstance(datos, int):
        return []                                            # un int cuenta como float
    if isinstance(datos, clase):
        return []
    return _error_tipo(ruta, clase.__name__, datos)


def _validar_typeddict(datos: object, esquema: type, ruta: str) -> list[str]:
    if not isinstance(datos, dict):
        return _error_tipo(ruta, "dict", datos)
    tipos = get_type_hints(esquema, include_extras=True)
    errores: list[str] = []
    for clave, tipo in tipos.items():
        if clave in datos:
            errores += validar(datos[clave], tipo, f"{ruta}.{clave}")
        elif clave in esquema.__required_keys__:
            errores.append(f"{ruta}.{clave}: falta la clave obligatoria")
    for clave in datos:
        if clave not in tipos:
            errores.append(f"{ruta}.{clave}: clave no permitida")
    return errores


def validar(datos: object, esquema: object, ruta: str = "$") -> list[str]:
    origen = get_origin(esquema)

    # Envoltorios transparentes y alias
    if origen in _ENVOLTORIOS:
        return validar(datos, get_args(esquema)[0], ruta)
    if isinstance(esquema, TypeAliasType):
        return validar(datos, esquema.__value__, ruta)

    # Formas especiales
    if esquema is Any:
        return []
    if esquema is None or esquema is type(None):
        return [] if datos is None else _error_tipo(ruta, "None", datos)
    if origen is Annotated:
        base, *metadatos = get_args(esquema)
        errores = validar(datos, base, ruta)
        if errores:
            return errores
        for meta in metadatos:
            comprobar = getattr(meta, "comprobar", None)
            if callable(comprobar):
                mensaje = comprobar(datos)
                if isinstance(mensaje, str):
                    errores.append(f"{ruta}: {mensaje}")
        return errores
    if origen is Literal:
        permitidos = get_args(esquema)
        if any(datos == p and type(datos) is type(p) for p in permitidos):
            return []
        return [f"{ruta}: valor no permitido {datos!r}"]
    if origen is Union:
        if any(not validar(datos, opcion, ruta) for opcion in get_args(esquema)):
            return []
        return [f"{ruta}: ningún tipo de la unión encaja"]

    # Contenedores
    if origen is list:
        if not isinstance(datos, list):
            return _error_tipo(ruta, "list", datos)
        (tipo_elemento,) = get_args(esquema)
        errores = []
        for i, elemento in enumerate(datos):
            errores += validar(elemento, tipo_elemento, f"{ruta}[{i}]")
        return errores
    if origen is dict:
        if not isinstance(datos, dict):
            return _error_tipo(ruta, "dict", datos)
        _, tipo_valor = get_args(esquema)
        errores = []
        for clave, valor in datos.items():
            errores += validar(valor, tipo_valor, f"{ruta}.{clave}")
        return errores
    if is_typeddict(esquema):
        return _validar_typeddict(datos, esquema, ruta)

    # Clases simples
    if origen is None and isinstance(esquema, type):
        return _validar_clase(datos, esquema, ruta)
    raise TypeError(f"esquema no soportado: {esquema!r}")

