import unittest
from collections.abc import Callable
from dataclasses import dataclass
from datetime import date, timedelta
from typing import Protocol
from unittest.mock import Mock

PLAZO = timedelta(days=14)


class Notificador(Protocol):
    def enviar(self, destinatario: str, mensaje: str) -> None: ...


@dataclass
class _Libro:
    titulo: str
    socio: str | None = None
    limite: date | None = None


class Biblioteca:
    def __init__(self, notificador: Notificador, hoy: Callable[[], date] = date.today) -> None:
        self._notificador = notificador
        self._hoy = hoy
        self._libros: dict[str, _Libro] = {}

    def alta(self, isbn: str, titulo: str) -> None:
        if isbn in self._libros:
            raise ValueError(f"el ISBN {isbn} ya está registrado")
        self._libros[isbn] = _Libro(titulo)

    def prestar(self, isbn: str, socio: str) -> date:
        libro = self._libros[isbn]                  # KeyError si no existe
        if libro.socio is not None:
            raise ValueError(f"«{libro.titulo}» ya está prestado")
        libro.socio = socio
        libro.limite = self._hoy() + PLAZO
        return libro.limite

    def devolver(self, isbn: str) -> int:
        libro = self._libros[isbn]
        if libro.socio is None or libro.limite is None:
            raise ValueError(f"«{libro.titulo}» no está prestado")
        retraso = max(0, (self._hoy() - libro.limite).days)
        if retraso > 0:
            self._notificador.enviar(libro.socio, f"Días de retraso: {retraso}")
        libro.socio = None
        libro.limite = None
        return retraso

    def disponibles(self) -> list[str]:
        return sorted(libro.titulo for libro in self._libros.values() if libro.socio is None)


class TestBiblioteca(unittest.TestCase):
    def setUp(self):
        self.fecha = date(2026, 3, 1)
        self.notificador = Mock()
        self.bib = Biblioteca(self.notificador, hoy=lambda: self.fecha)
        self.bib.alta("111", "Rayuela")
        self.bib.alta("222", "Ficciones")

    def test_prestar_devuelve_la_fecha_limite_a_14_dias(self):
        self.assertEqual(self.bib.prestar("111", "ana"), date(2026, 3, 15))

    def test_no_se_puede_prestar_dos_veces(self):
        self.bib.prestar("111", "ana")
        with self.assertRaises(ValueError):
            self.bib.prestar("111", "luis")

    def test_isbn_desconocido_lanza_key_error(self):
        with self.assertRaises(KeyError):
            self.bib.prestar("999", "ana")

    def test_devolucion_a_tiempo_no_avisa(self):
        self.bib.prestar("111", "ana")
        self.fecha = date(2026, 3, 15)              # justo el último día
        self.assertEqual(self.bib.devolver("111"), 0)
        self.notificador.enviar.assert_not_called()

    def test_devolucion_con_retraso_avisa_al_socio(self):
        self.bib.prestar("111", "ana")
        self.fecha = date(2026, 3, 18)
        self.assertEqual(self.bib.devolver("111"), 3)
        self.notificador.enviar.assert_called_once_with("ana", "Días de retraso: 3")

    def test_disponibles_ordenados_y_sin_prestados(self):
        self.bib.alta("333", "Aura")
        self.assertEqual(self.bib.disponibles(), ["Aura", "Ficciones", "Rayuela"])
        self.bib.prestar("222", "ana")
        self.assertEqual(self.bib.disponibles(), ["Aura", "Rayuela"])

    def test_alta_duplicada_lanza_value_error(self):
        with self.assertRaises(ValueError):
            self.bib.alta("111", "Otra")

