def _hoy_prohibido():
    raise AssertionError("Se ha usado la fecha real (date.today): pasa tu propio hoy= a Biblioteca en las pruebas")

class _Referencia:
    _plazo = 14
    _ajuste = 0
    _avisar = True
    _avisar_siempre = False
    _comprobar_prestado = True
    _ordenar = True

    def __init__(self, notificador, hoy=_hoy_prohibido):
        self._notificador = notificador
        self._hoy = hoy
        self._libros = {}

    def alta(self, isbn, titulo):
        if isbn in self._libros:
            raise ValueError("ISBN duplicado")
        self._libros[isbn] = [titulo, None, None]

    def prestar(self, isbn, socio):
        libro = self._libros[isbn]
        if self._comprobar_prestado and libro[1] is not None:
            raise ValueError("ya prestado")
        libro[1] = socio
        libro[2] = self._hoy() + _timedelta(days=self._plazo)
        return libro[2]

    def devolver(self, isbn):
        libro = self._libros[isbn]
        if libro[1] is None:
            raise ValueError("no prestado")
        retraso = max(0, (self._hoy() - libro[2]).days + self._ajuste)
        if self._avisar and (retraso > 0 or self._avisar_siempre):
            self._notificador.enviar(libro[1], f"Días de retraso: {retraso}")
        libro[1] = libro[2] = None
        return retraso

    def disponibles(self):
        titulos = [t for t, socio, _ in self._libros.values() if socio is None]
        return sorted(titulos) if self._ordenar else titulos

